              folioOrden: number;
              /** @description Modelo de la orden. */
              idModelo: number;
              /** @description Código/nombre del modelo (para la UI). */
              modelo: string;
              /** @description Σ piezas color×talla de la orden (base del cálculo). */
              totalPiezas: number;
